/* Bilingual literature review. Research snapshot: 2026-10-13.
   Figures labelled conceptual are original explanatory illustrations.
   Paper results are author-reported, not independently reproduced. */
window.buildContent = function (lang) {
  const t = (zh, en) => lang === 'en' ? en : zh;
  const P = {
    nmf:'https://www.merl.com/publications/TR2003-139',
    onsets:'https://arxiv.org/abs/1710.11153v2',
    slakh:'https://arxiv.org/abs/1909.08494',
    mt3:'https://arxiv.org/abs/2111.03017v4',
    jointist:'https://arxiv.org/abs/2302.00286v2',
    perceiver:'https://arxiv.org/abs/2306.10785',
    yourmt3:'https://arxiv.org/abs/2407.04822v3',
    mu:'https://arxiv.org/html/2607.08168v2',
    challenge:'https://arxiv.org/abs/2603.27528',
    harmonica:'https://arxiv.org/abs/2609.04640v1',
    tutti:'https://arxiv.org/abs/2609.00640'
  };
  const src = (...keys) => keys.map(k => ({label:({nmf:'NMF · 2003',onsets:'Onsets & Frames · 2018',slakh:'Slakh · 2019',mt3:'MT3 · 2022',jointist:'Jointist · 2023',perceiver:'Perceiver TF · 2023',yourmt3:'YourMT3+ · 2024',mu:'MuScriptor · v2 / 2026',challenge:'AMT Challenge · 2026',harmonica:'Harmonica · 2026',tutti:'TUTTI · 2026'})[k],url:P[k]}));
  const card = (tag,title,body,cls='')=>`<div class="card ${cls}"><span class="tag">${tag}</span><h3>${title}</h3><p>${body}</p></div>`;
  const takeaway = s=>`<div class="takeaway"><b>${t('要点','KEY POINT')}</b>${s}</div>`;
  const diagram = (name,alt)=>`<figure class="diagram"><img src="assets/diagrams/${name}-${lang}.svg" alt="${alt}" loading="lazy"><figcaption>${t('原创概念示意，非模型实验输出。','Original conceptual illustration; not an experimental model output.')}</figcaption></figure>`;
  const nodes = items=>`<div class="flow">${items.map((x,i)=>`${i?'<span class="arrow" aria-hidden="true">→</span>':''}<div class="node ${x[2]||''}"><b>${x[0]}</b><small>${x[1]}</small></div>`).join('')}</div>`;
  const link=(url,label)=>`<a class="pill-link" href="${url}" target="_blank" rel="noopener noreferrer">${label} ↗</a>`;
  const attr = s => String(s).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const paperAccess = (id, section, page) => [
    {label:t('arXiv 原文','Paper on arXiv'),url:`https://arxiv.org/abs/${id}`},
    {label:t(`原文 §${section[0]}`,`Read §${section[0]}`),url:`https://arxiv.org/html/${id}#${section[1]}`},
    {label:t(`PDF 第 ${page} 页`,`PDF · page ${page}`),url:`https://arxiv.org/pdf/${id}#page=${page}`}
  ];
  const paperFigure = ({id, image, title, alt, paper, anchor, page, number, credit, steps, portrait=false}) => {
    const url=`https://arxiv.org/html/${paper}#${anchor}`;
    return `<section class="source-figure${portrait?' portrait':''}" id="${id}"><header class="source-figure-head"><h3>${title}</h3><span class="original-badge">${t('论文原图 · 点击放大','ORIGINAL FIGURE · CLICK TO ENLARGE')}</span></header><div class="source-figure-body"><figure><button class="figure-open" data-figure-src="${image}" data-figure-title="${attr(title)}" data-figure-source="${url}" aria-label="${attr(t('放大：','Enlarge: ')+title)}"><img src="${image}" alt="${attr(alt)}" loading="lazy"></button><figcaption>${credit}</figcaption></figure><ol class="figure-reading">${steps.map((step,i)=>`<li><span class="step-no">${String(i+1).padStart(2,'0')}</span><div><strong>${step[0]}</strong><p>${step[1]}</p></div></li>`).join('')}</ol></div><div class="source-figure-links"><a href="${url}" target="_blank" rel="noopener noreferrer">${t(`原文 Figure ${number}`,`Figure ${number} in the paper`)} ↗</a><a href="https://arxiv.org/pdf/${paper}#page=${page}" target="_blank" rel="noopener noreferrer">${t(`PDF 第 ${page} 页`,`PDF · page ${page}`)} ↗</a></div></section>`;
  };
  const heroWave = Array.from({length:62},(_,i)=>`<i style="height:${10+Math.abs(Math.sin(i*1.49)*Math.cos(i*.19))*85}px"></i>`).join('');
  const rollNotes = [[4,72,16,0],[23,48,13,0],[42,24,19,0],[67,48,23,0],[5,145,25,1],[34,121,24,1],[66,145,26,1],[14,96,19,2],[37,72,14,2],[59,96,20,2],[81,24,13,2]].map(n=>`<span class="note" style="left:${n[0]}%;top:${n[1]}px;width:${n[2]}%;background:${['#e8a371','#7cb8b0','#92a9d4'][n[3]]}"></span>`).join('');
  const slides = [
  {id:'intro',chapter:'start',kicker:'MULTI-INSTRUMENT MUSIC TRANSCRIPTION · LITERATURE REVIEW',
    title:t('多乐器<span class="hero-accent">音乐转录</span>','Multi-instrument<br><span class="hero-accent">Music Transcription</span>'),
    lead:t('多乐器自动音乐转录的任务定义、建模方法与代表性文献。围绕音符表示、数据与评测梳理研究挑战，并重点分析 MuScriptor 的架构、训练策略和实验结果。','A review of task definitions, modeling approaches and representative literature in multi-instrument automatic music transcription. Note representations, data and evaluation frame the research challenges, with a detailed analysis of MuScriptor’s architecture, training strategy and empirical results.'),
    html:`<div class="hero-meta"><span>中文 / ENGLISH</span><span>REVIEWED 2026.10.13</span></div><div class="hero-actions"><button class="primary" data-start>${t('进入演示','Presentation mode')} ↗</button><a class="text-link" href="#library">${t('文献库','Paper library')} →</a></div><div class="hero-visual" role="img" aria-label="${t('概念图：混合音频波形变为钢琴、贝斯、长笛三个音符轨道','Conceptual mixture waveform and three note tracks for piano, bass and flute')}"><div><div class="visual-caption">01 / THE MIXTURE</div><div class="waveform">${heroWave}</div><p class="signal-label">${t('一个录音。许多相互重叠的音符。','One recording. Many overlapping notes.')}</p><div class="visual-foot">${t('原创示意 · 不是模型输出','ILLUSTRATION · NOT A MODEL OUTPUT')}</div></div><div><div class="visual-caption">02 / THE MUSICAL EVENTS</div><div class="roll">${rollNotes}</div><div class="roll-key"><span style="--color:#e8a371">${t('钢琴','Piano')}</span><span style="--color:#7cb8b0">${t('贝斯','Bass')}</span><span style="--color:#92a9d4">${t('长笛','Flute')}</span><span>${t('横轴：时间 · 纵轴：音高','TIME → · PITCH ↑')}</span></div></div></div>`,
    note:t("多乐器音乐转录需要从混合音频恢复带有乐器标签的音符事件。本文从任务定义、代表性方法、数据与评测切入，重点分析 MuScriptor，并区分论文证据、概念示意与尚未解决的问题。","Multi-instrument music transcription recovers instrument-labelled note events from mixed audio. This review examines the task, representative methods, data and evaluation, then analyzes MuScriptor while distinguishing empirical evidence, conceptual illustrations and open questions."),sources:[]},
  {id:'task',chapter:'start',kicker:'THE TASK',
    title:t("任务定义：从音频恢复音符事件","Task definition: from audio to note events"),
    lead:t('核心问题只有四个：谁、弹了什么音、何时开始、何时结束。多乐器意味着还要把音符分配给正确的乐器类别。','Four questions: which instrument, which pitch, when did it start, and when did it end? Multi-instrument transcription also assigns each note to an instrument class.'),
    html:diagram('task',t('音频混音经过转录模型，得到按乐器区分的钢琴卷帘图','A mixture is transcribed into instrument-labelled piano rolls'))+`<div class="grid three mt">${card('POLYPHONIC',t('复音 ≠ 多乐器','Polyphonic ≠ multi-instrument'),t('一台钢琴就能同时弹多个音。多音高检测未必知道“是谁弹的”。','A piano can play several notes at once. Multi-pitch detection need not identify who played them.'))}${card('AUDIO → EVENTS',t('转录 ≠ 音源分离','Transcription ≠ separation'),t('分离输出音频分轨；转录输出符号事件。分离可以帮忙，但不是必经步骤。','Separation outputs audio stems; transcription outputs symbolic events. Separation can help, but is optional.'))}${card('EVENTS → SCORE',t('MIDI ≠ 可读乐谱','MIDI ≠ readable notation'),t('节拍、节奏量化、声部分配和排版，还需要进一步处理。','Meter, rhythmic quantization, voices and engraving still need additional decisions.'))}</div>`,
    note:t("钢琴卷帘图中，横向位置表示起音，长度表示时值，纵向位置表示音高，颜色表示乐器。力度、踏板与弯音也是潜在目标，但并非所有模型都预测。两个同类乐器的演奏者不一定被分成两条轨。","In a piano roll, horizontal position denotes onset, length denotes duration, height denotes pitch and color denotes instrument. Velocity, pedal and bends are possible targets but are not predicted by every model. Two players of the same instrument are not necessarily assigned separate tracks."),sources:src('mt3','yourmt3')},
  {id:'listen',chapter:'start',kicker:'AUDITORY EXAMPLE',
    title:t("混合音频与声部感知","Auditory perception of mixed parts"),
    lead:t('勾选声部，播放一个 4 秒的合成小例子。先听全部，再只听一个声部：人也会借助音色、音域和旋律连续性来“分组”。','Select parts and play a four-second synthetic example. Listen to the mixture, then one part: we use timbre, register and melodic continuity to group notes.'),
    html:`<div id="audio-demo" class="card"><span class="tag">${t('可交互听觉示意','INTERACTIVE LISTENING EXAMPLE')}</span><h3>${t('三声部合成示例','A three-part synthetic example')}</h3><div class="demo-controls"><label><input type="checkbox" data-stem="piano" checked> ${t('钢琴式音色','Piano-like')}</label><label><input type="checkbox" data-stem="bass" checked> ${t('贝斯式音色','Bass-like')}</label><label><input type="checkbox" data-stem="flute" checked> ${t('长笛式音色','Flute-like')}</label><button class="primary" data-audio="play">▶ ${t('播放 4 秒','Play 4 seconds')}</button><button data-audio="stop">■ ${t('停止','Stop')}</button></div><p class="listen-status" id="listen-status" aria-live="polite"></p><p class="listen-note">${t('浏览器振荡器生成的原创合成示例，音色仅作近似；不是任何模型的输入/输出对比，也不运行转录模型。音频仅在点击后播放。','An original synthetic example made with browser oscillators; timbres are approximate. This is not a model comparison and does not run transcription. Audio plays only after a click.')}</p></div>`+takeaway(t('听见某种乐器，比逐个写对它的所有音符容易得多。','Recognizing an instrument is easier than correctly writing out all of its notes.')),
    note:t("混合声部与单独声部的对照说明了音色、音域和旋律连续性如何影响听觉分组。这里的振荡器音色仅作近似；真实音乐还包含混响、失真与复杂演奏，因此这个例子不代表真实转录的完整难度。","Comparing mixed and isolated parts illustrates how timbre, register and melodic continuity influence auditory grouping. Oscillator timbres are approximate. Real music also contains reverberation, distortion and complex playing techniques, so the example does not capture the full transcription problem."),sources:[]},
  {id:'ambiguity',chapter:'problem',kicker:'ACOUSTIC AMBIGUITY',
    title:t("谐波重叠与乐器归属的歧义","Harmonic overlap and instrument ambiguity"),
    lead:t('频率高，不代表一定有一个更高的音符。它可能只是低音的泛音。两种乐器同时演奏，还会让这些线索互相遮挡。','A high-frequency peak need not mean a higher note: it may be an overtone of a lower note. Simultaneous instruments overlap and obscure these cues.'),
    html:diagram('ambiguity',t('C3 的第二谐波（第一泛音）与 C4 基频重合，说明频谱峰不等于独立音符','The second harmonic of C3 overlaps the fundamental of C4'))+`<div class="grid three mt">${card('01',t('归属不清','Uncertain ownership'),t('同音高、近似音色、重叠泛音：这个音到底属于谁？','Shared pitches, similar timbres and overlapping harmonics: whose note is it?'))}${card('02',t('边界不清','Uncertain boundaries'),t('柔和起音、重复音和混响尾音，让开始与结束变模糊。','Soft attacks, repeated notes and reverb blur note starts and ends.'))}${card('03',t('分布会变','Changing acoustics'),t('音源库里的吉他，与失真、压缩后的真实吉他并不相同。','A sampled guitar differs from a recorded guitar with distortion and compression.'))}</div>`,
    note:t("C3 与 C4 相差八度：C3 的第二谐波与 C4 的基频重合。图中峰高为示意，不能据此推断真实乐器。若两个演奏者同时发出相同音高，仅用音高集合无法区分两个音符实例；这一问题也涉及模型的事件表示能力。","C3 and C4 are an octave apart: the second harmonic of C3 overlaps the fundamental of C4. Peak heights are schematic and do not identify real instruments. When two performers play the same pitch simultaneously, a pitch set cannot distinguish two note instances, exposing a representation issue as well as an acoustic one."),sources:src('nmf','onsets','yourmt3')},
  {id:'methods',chapter:'problem',kicker:'MODELING APPROACHES',
    title:t("三类建模方法：分解、检测与事件解码","Three approaches: factorization, detection and event decoding"),
    lead:t('这些是帮助理解的路线，不是一张从“落后”到“先进”的排名表。现代系统经常组合其中的思想。','These are conceptual routes, not a ranking from obsolete to superior. Modern systems often combine ideas from several of them.'),
    html:diagram('methods',t('模板分解、逐帧神经检测、序列事件解码三种方法路线','Three routes: template factorization, frame-wise neural detection, and event-sequence decoding'))+takeaway(t('先问模型“用什么表示答案”，再问“用什么网络预测答案”。','Ask how the answer is represented before asking which network predicts it.')),
    note:t("NMF 用频谱模板及其激活解释混合信号；逐帧模型估计各时刻的音符活动；序列模型预测由时间、音高、乐器等符号构成的事件序列。输出表示决定模型能表达什么，网络结构与训练目标决定如何估计这些表示。","NMF explains a mixture through spectral templates and their activations; frame models estimate note activity over time; sequence models predict events encoding time, pitch and instrument. Output representations determine what a model can express, while architecture and training objectives determine how those representations are estimated."),sources:src('nmf','onsets','mt3')},
  {id:'landmarks',chapter:'literature',kicker:'THE FOUNDATIONS',
    title:t("基础工作：分解、起音建模与配对数据","Foundations: factorization, onset modeling and paired data"),
    lead:t('三类基础贡献：可解释的分解、起音与延音分开建模，以及可扩展的配对数据。','Three foundational contributions: interpretable factorization, separate attack and sustain modeling, and scalable paired data.'),
    html:`<div class="timeline"><div class="milestone"><span class="year">2003</span><div><b>NMF</b><p>Smaragdis & Brown · WASPAA</p></div><div class="thought">${t('X ≈ WH：频谱 ≈ 模板 × 激活。结构清晰，但音色变化和重叠谐波很难处理。它是基础，不是通用多乐器系统。','X ≈ WH: spectrogram ≈ templates × activations. Interpretable, but changing timbre and overlapping harmonics are difficult. A foundation, not a general multi-instrument system.')}</div></div><div class="milestone"><span class="year">2018</span><div><b>Onsets and Frames</b><p>Hawthorne et al. · ISMIR</p><span class="tag">${t('仅钢琴 · 概念桥梁','PIANO ONLY · CONCEPTUAL BRIDGE')}</span></div><div class="thought">${t('分别问“刚开始了吗”和“还在响吗”；起音预测帮助帧预测，也约束解码。未解决多乐器归属。','Separate “did it start?” from “is it still active?” Onsets inform frame prediction and constrain decoding. It does not solve multi-instrument attribution.')}</div></div><div class="milestone"><span class="year">2019</span><div><b>Slakh</b><p>Manilow et al. · WASPAA</p><span class="tag">${t('数据集 · 非转录模型','DATASET · NOT A TRANSCRIPTION MODEL')}</span></div><div class="thought">${t('MIDI 经虚拟乐器渲染，得到混音、分轨和精确标签。Slakh2100 首版约145小时；合成标签易得，真实迁移仍要验证。','Render MIDI into mixtures and stems with aligned labels. The first Slakh2100 release provides about 145 hours; easy labels do not guarantee real-world transfer.')}</div></div></div>`+takeaway(t('任务、标签和表示方式，往往与网络架构一样重要。','The task, labels and representation matter as much as the architecture.')),
    note:t("NMF 提供可解释的分解框架；Onsets and Frames 将起音与持续状态分开建模，但范围是钢琴；Slakh 提供可扩展的多乐器配对数据。这三项工作的贡献类型与任务范围不同，不构成同一基准上的连续模型排名。","NMF provides an interpretable factorization framework. Onsets and Frames separates onset and sustained activity modeling within piano transcription. Slakh supplies scalable paired multi-instrument data. These contributions differ in type and scope and are not successive entries in one benchmark ranking."),sources:src('nmf','onsets','slakh')},
  {id:'onsets-frames',chapter:'literature',kicker:'ONSETS AND FRAMES · ISMIR 2018',
    title:t('Onsets and Frames：起音如何帮助帧预测','Onsets and Frames: how onsets inform frame predictions'),
    lead:t('这项钢琴转录工作把“音符刚开始”与“音符仍在持续”分开建模，再让两种预测相互配合。图中横向连接体现了核心设计。','This piano transcription model separates note attacks from sustained activity, then connects the predictions. The cross-branch connection is central to the design.'),
    paperLinks:paperAccess('1710.11153v2',['3','S3'],3),
    html:paperFigure({id:'figure-onsets',image:'assets/papers/onsets-frames-architecture.svg',title:t('Figure 1 · 双分支网络架构','Figure 1 · Dual-branch network architecture'),alt:t('原论文架构图：底部频谱输入两个卷积堆栈，右侧起音预测连接左侧帧预测网络','Original architecture: a spectrogram feeds two convolution stacks; onset predictions on the right condition the frame network on the left'),paper:'1710.11153v2',anchor:'S3.F1',page:3,number:1,portrait:true,credit:t('Hawthorne et al. (2018), Fig. 1 · CC BY 4.0 · 原样转载。','Hawthorne et al. (2018), Fig. 1 · CC BY 4.0 · Reproduced unchanged.'),steps:[
      [t('底部：共享输入，独立特征','Bottom: shared input, separate features'),t('同一 Log Mel-Spectrogram 进入两个独立 Conv Stack，分别学习起音与持续活动的声学特征。','The same log-Mel spectrogram enters two separate convolution stacks, learning features for attacks and sustained activity.')],
      [t('右侧：检测音符开始','Right: detect note attacks'),t('Conv Stack → BiLSTM → FC Sigmoid → Onset Predictions。每个输出表示某个钢琴音高是否正在起音。','Conv Stack → BiLSTM → FC Sigmoid → Onset Predictions. Outputs estimate whether each piano pitch is starting.')],
      [t('横向连接：用起音约束延音','Across branches: condition sustained activity'),t('起音预测连接到左侧 BiLSTM，帮助 Frame Predictions。推断时还要求起音检测支持，才允许新音符开始。','Onset predictions enter the left BiLSTM to inform Frame Predictions. At inference, an onset detection is also required to start a new note.')]
    ]})+takeaway(t('图1是原始双分支设计，没有独立 offset head；§3.1 的力度分支未画入此图。任务范围是钢琴，不涉及多乐器归属。','Figure 1 shows the original dual-branch design, without a separate offset head. The velocity branch in §3.1 is omitted. The task is piano transcription, without multi-instrument attribution.')),
    note:t('按底部→右侧→横向连接的顺序阅读原图。起音在这里有两个作用：作为帧网络的条件，以及推断时新音符的门控。不能把后来扩展版本的 offset 分支误读为这篇论文图1的一部分。','Read from the bottom to the right branch, then across the connecting arrow. Onsets both condition the frame network and gate new notes at inference. An offset branch from a later expanded version is not part of this Figure 1.'),sources:src('onsets')},
  {id:'mt3',chapter:'literature',kicker:'MT3 · ICLR 2022',
    title:t('MT3：一个模型连接多个数据集与乐器','MT3: one model across datasets and instruments'),
    lead:t('MT3 将不同数据集的音频与标注转换为统一的输入输出格式，用同一个编码器—解码器 Transformer 学习多轨转录。','MT3 converts audio and annotations from different datasets into shared input and output formats, training one encoder–decoder Transformer for multitrack transcription.'),
    paperLinks:paperAccess('2111.03017v4',['3.1','S3.SS1'],3),
    html:paperFigure({id:'figure-mt3-overview',image:'assets/papers/mt3-overview.png',title:t('Figure 1 · 多任务转录框架','Figure 1 · Multitask transcription overview'),alt:t('MT3原图：六个数据集的频谱共享一个MT3模型，输出按乐器区分的钢琴卷帘','Original MT3 overview: spectrograms from six datasets share one model and yield instrument-specific piano rolls'),paper:'2111.03017v4',anchor:'S1.F1',page:2,number:1,credit:t('Gardner et al. (2022), Fig. 1 · CC BY 4.0 · 原样转载。图标作者见论文','Gardner et al. (2022), Fig. 1 · CC BY 4.0 · Reproduced unchanged. Icon creators: paper ')+`<a href="https://arxiv.org/html/2111.03017v4#A6" target="_blank" rel="noopener noreferrer">Appendix F</a>`,steps:[
      [t('左侧：不同数据来源','Left: different data sources'),t('六行频谱代表六个数据集；数据的乐器范围与标签不同，但都进入同一训练框架。','Six spectrogram rows represent six datasets. Instrument coverage and annotations differ, but all enter a shared training framework.')],
      [t('中央：共享 Transformer','Center: shared Transformer'),t('音频频谱由编码器处理；解码器自回归生成事件 token。图1只画出 MT3 总体模块，内部结构详见 §3.1。','An encoder processes audio spectra and an autoregressive decoder generates event tokens. Figure 1 shows the overall MT3 module; §3.1 specifies its internals.')],
      [t('右侧：重建多轨音符','Right: reconstruct multitrack notes'),t('生成的事件序列还原为按乐器区分的音符轨道。右侧 piano roll 是输出可视化，不是模型直接预测的图像。','Generated event sequences reconstruct instrument-labelled note tracks. The piano rolls visualize the output; the model does not predict these images.')]
    ]})+takeaway(t('关键统一发生在输入输出表示与训练任务上。图1是框架概览，不是逐层网络结构图；下一页对应原文的事件编码图。','The unification concerns representations and training tasks. Figure 1 is a framework overview, not a layer-by-layer architecture diagram; the next section examines the original event-encoding figure.')),
    note:t('多任务训练共享模型参数和事件词表，不等于所有数据集都有相同乐器或相同标签完整性。MT3 内部采用编码器—解码器结构；这一点可直接打开 §3.1 对照。','Multitask training shares parameters and an event vocabulary; datasets need not have identical instruments or label coverage. MT3 uses an encoder–decoder architecture, specified in §3.1.'),sources:src('mt3')},
  {id:'mt3-events',chapter:'literature',kicker:'MT3 · EVENT REPRESENTATION',
    title:t('MT3：音符如何变成可预测的事件序列','MT3: turning notes into a predictable event sequence'),
    lead:t('事件词表将时间、乐器与音高写成序列，使多乐器转录成为条件序列生成任务。训练时编码标注，推断时反向还原音符。','An event vocabulary serializes time, instrument and pitch, making transcription a conditional sequence-generation task. Annotations are tokenized for training; predicted tokens are decoded back into notes.'),
    paperLinks:paperAccess('2111.03017v4',['3.2','S3.SS2'],4),
    html:paperFigure({id:'figure-mt3-tokens',image:'assets/papers/mt3-tokenization.png',title:t('Figure 2 · Tokenization / Detokenization','Figure 2 · Tokenization / Detokenization'),alt:t('原文图2：左侧不同乐器的音符通过tokenization变为右侧时间、program、开关音和音高序列，detokenization还原音符','Original Figure 2: coloured notes are tokenized into time, program, on/off and pitch events; detokenization reconstructs notes'),paper:'2111.03017v4',anchor:'S3.F2',page:4,number:2,credit:t('Gardner et al. (2022), Fig. 2 · CC BY 4.0 · 原样转载。','Gardner et al. (2022), Fig. 2 · CC BY 4.0 · Reproduced unchanged.'),steps:[
      [t('左 → 右：编码训练目标','Left → right: encode training targets'),t('颜色区分乐器。Tokenization 将参考音符写成序列；左侧钢琴卷帘是符号标注，模型输入仍是音频频谱。','Colors distinguish instruments. Tokenization serializes reference notes. The piano roll is an annotation; the neural input remains an audio spectrogram.')],
      [t('右侧：读取状态与事件','Right: read states and events'),t('&lt;time&gt; 设置片段内时间，&lt;prog&gt; 设置乐器，&lt;on/off&gt; 设置状态，&lt;note&gt; 指定音高。状态持续到下一次对应变化。','&lt;time&gt; sets within-segment time, &lt;prog&gt; the instrument, &lt;on/off&gt; the state, and &lt;note&gt; the pitch. States persist until their next change.')],
      [t('右 → 左：还原预测','Right → left: reconstruct predictions'),t('推断时逐个预测 token，再经 Detokenization 还原多轨 MIDI。乐器身份与音符时间都必须在序列中表达。','At inference, tokens are predicted autoregressively and detokenized into multitrack MIDI. Both instrument identity and note timing must be represented in the sequence.')]
    ]})+`<div class="grid two mt">${card('TIME',t('绝对时间与分段衔接','Absolute time and chunk continuity'),t('原始 MT3 使用2.048秒片段、10毫秒时间分辨率。时间 token 是片段内绝对位置；tie 声明跨片段延续的音符，这一机制未画入图2。','Original MT3 uses 2.048-second segments and 10 ms resolution. Time tokens encode absolute positions within each segment; a tie section declares continuing notes, a mechanism not drawn in Figure 2.'))}${card('BOUNDARIES',t('统一词表仍有表示边界','A shared vocabulary still has limits'),t('密集复音、乐器身份与跨片段连续性仍需处理。原始多乐器 MT3 不预测细粒度力度。','Dense polyphony, instrument identity and cross-chunk continuity remain challenging. The original multi-instrument MT3 does not predict graded velocity.'))}</div>`,
    note:t('图2展示符号表示的双向转换，不是模型把钢琴卷帘作为输入。讲解时可沿右侧示例依次读 time、program、on/off 和 note，注意只有状态变化才需要再次写入相应 token。','Figure 2 depicts conversion between symbolic representations, not piano-roll input to the neural model. Follow time, program, on/off and note tokens on the right, noting that state tokens need to recur only when their values change.'),sources:src('mt3')},
  {id:'modern',chapter:'literature',kicker:'JOINTIST · 2023',
    title:t('Jointist：让转录与音源分离相互促进','Jointist: connecting transcription and source separation'),
    lead:t('系统连接乐器识别、条件转录与音源分离。乐器信息告诉模型关注哪个声部，预测的 piano roll 为分离提供音高与时间线索。','The system connects instrument recognition, conditioned transcription and source separation. Instrument information identifies the target part, while predicted piano rolls supply pitch and timing cues to separation.'),
    paperLinks:paperAccess('2302.00286v2',['3','S3'],4),
    html:paperFigure({id:'figure-jointist',image:'assets/papers/jointist-architecture.png',title:t('Figure 1 · Jointist 系统架构','Figure 1 · Jointist system architecture'),alt:t('Jointist原图：橙色乐器识别、蓝色条件转录和绿色音源分离模块依次连接，转录的音高后验辅助分离','Original Jointist diagram: orange instrument recognition conditions blue transcription; pitch posteriors and instrument conditions guide green source separation'),paper:'2302.00286v2',anchor:'S3.F1',page:4,number:1,credit:t('Cheuk et al. (2023), Fig. 1 · CC BY 4.0 · 原样转载。','Cheuk et al. (2023), Fig. 1 · CC BY 4.0 · Reproduced unchanged.'),steps:[
      [t('橙色：识别乐器集合','Orange: recognize instruments'),t('f_IR 从混合音频的 Mel 频谱预测乐器；得到的条件向量指定后续模块处理哪个乐器，也可由用户提供。','f_IR predicts instruments from the mixture’s Mel spectrogram. Condition vectors specify the instrument for downstream modules and can also be supplied by a user.')],
      [t('蓝色：逐乐器预测音符','Blue: transcribe each instrument'),t('f_T 结合混音 Mel 特征和乐器条件，预测 pitch posteriors。虚线表示对 K 种乐器重复此过程。','f_T combines mixture Mel features with instrument conditions to predict pitch posteriors. Dashed paths repeat this process for K instruments.')],
      [t('绿色：音符指导分离','Green: notes guide separation'),t('f_MSS 使用混音 STFT、乐器条件与预测 piano roll 输出分轨。识别器单独训练，转录与分离模块进行联合优化。','f_MSS uses mixture STFT features, instrument conditions and predicted piano rolls to produce stems. Recognition is trained separately; transcription and separation are optimized jointly.')]
    ]})+takeaway(t('这里的信息流是“条件转录 → 音符辅助分离”。图1省略了部分音频输入连线；§3说明转录器也接收混音的 Mel 频谱。','The information flow is conditioned transcription followed by note-guided separation. Figure 1 omits some audio-input arrows; §3 specifies that the transcriber also receives the mixture’s Mel spectrogram.')),
    note:t('按橙、蓝、绿模块解释信息流。转录与分离共享有用的监督信号，但不是先分离音频再逐轨转录，也不是识别、转录、分离三个模块全部联合训练。乐器识别错误可能影响后续结果。','Follow the orange, blue and green modules. Transcription and separation share useful supervision; this is not a separation-first pipeline, nor are all three modules jointly trained. Recognition errors may propagate downstream.'),sources:src('jointist')},
  {id:'yourmt3',chapter:'literature',kicker:'YOURMT3+ · MLSP 2024',
    title:t('YourMT3+：时频编码、多通道解码与数据增强','YourMT3+: time–frequency encoding, multichannel decoding and augmentation'),
    lead:t('图1把三项改进放在一起：更有结构的音频编码、按乐器组并行的事件解码，以及跨数据集混合分轨的训练方法。','Figure 1 brings together structured audio encoding, parallel event decoding by instrument group, and training with stems mixed across datasets.'),
    paperLinks:paperAccess('2407.04822v3',['3','S3'],2),
    html:paperFigure({id:'figure-yourmt3',image:'assets/papers/yourmt3-architecture.png',title:t('Figure 1 · YPTF.MoE + Multi 与训练增强','Figure 1 · YPTF.MoE + Multi and training augmentation'),alt:t('YourMT3+原文图1：左侧PerceiverTF与MoE编码器，中部并行共享参数解码器，右侧跨数据集分轨增强','Original YourMT3+ Figure 1: PerceiverTF with MoE on the left, parallel weight-shared decoders in the center, cross-dataset stem augmentation on the right'),paper:'2407.04822v3',anchor:'S2.F1',page:2,number:1,credit:t('Chang et al. (2024), Fig. 1 · 从原文PDF第2页裁取图像，未重绘或改色；版权归原权利人。','Chang et al. (2024), Fig. 1 · Cropped from PDF page 2 without redrawing or recoloring; copyright remains with the original rights holders.'),steps:[
      [t('左侧：查询时频信息','Left: query time–frequency features'),t('可学习查询读取频谱；局部与时间维度模块交替处理，前馈层采用 MoE。§3.1说明该变体使用 log-magnitude 频谱与 ResNet 预编码器。','Learned queries read spectral features; local and temporal blocks alternate, with MoE feedforward layers. §3.1 specifies log-magnitude spectra and a ResNet pre-encoder for this variant.')],
      [t('中部：按乐器组解码','Center: decode by instrument group'),t('多个通道并行生成事件序列，解码器参数共享，各通道内部仍为自回归。这使未标注乐器组的损失可以被屏蔽。','Channels generate event sequences in parallel using shared decoder parameters; each channel remains autoregressive. Losses can be masked for unannotated instrument groups.')],
      [t('右侧：重新组合训练混音','Right: remix training examples'),t('跨数据集抽取带标签的分轨，重新混合并增强。右侧是训练时的数据构造过程，不是推断时必须执行的分离模块。','Labelled stems are sampled across datasets, remixed and augmented. This is training-data construction, not a required source-separation stage at inference.')]
    ]})+`<div class="callout">${t('<b>监督的关键：</b>录音里有声音但没有相应标签时，不能直接将其视为“乐器不存在”。多通道损失屏蔽避免把未标注声部当作负例；整体增益也不能全部归因于 MoE。','<b>Supervision matters:</b> an audible part without annotations should not be treated as absent. Channel-wise loss masking avoids turning unannotated parts into negative examples; overall gains cannot all be attributed to MoE.')}</div>`,
    note:t('图中展示最终的 YPTF.MoE+Multi 变体。图注对频谱使用概括性称呼，具体输入以 §3.1 的 log-magnitude 说明为准。编码器、解码器与训练增强是不同层面的改变，消融实验比单看总分更能说明贡献。','The figure shows the final YPTF.MoE+Multi variant. For its exact input, use the log-magnitude specification in §3.1 rather than the caption’s generic spectrogram wording. Encoder, decoder and augmentation changes address different parts of the system; ablations are needed to separate their contributions.'),sources:src('perceiver','yourmt3')},
  {id:'metrics',chapter:'evidence',kicker:'METRICS · MATCHING & F1',
    title:t('评测指标：匹配规则与 F1','Evaluation metrics: matching rules and F1'),
    lead:t('先定义什么算匹配，再统计误报与漏检。同一个预测，在不同指标下可能得到不同的评价。','Define a match first, then count false positives and missed notes. Different metrics can judge the same prediction differently.'),
    paperLinks:[{label:t('MuScriptor · 指标 §3.3','MuScriptor · metrics §3.3'),url:'https://arxiv.org/html/2607.08168v2#S3.SS3'},{label:t('Harmonica · 指标 §4.1','Harmonica · metrics §4.1'),url:'https://arxiv.org/html/2609.04640v1#S4.SS1'}],
    html:`<div class="metrics-layout"><div class="metrics-score"><h3>${t('Precision、Recall 与 F1','Precision, recall and F1')}</h3><dl class="metrics-formulas"><div><dt>Precision</dt><dd><b>TP / (TP + FP)</b><span>${t('预测的音符里，多少能匹配参考？','How many predicted notes match a reference?')}</span></dd></div><div><dt>Recall</dt><dd><b>TP / (TP + FN)</b><span>${t('参考音符里，多少被找到了？','How many reference notes were recovered?')}</span></dd></div><div><dt>F1</dt><dd><b>2TP / (2TP + FP + FN)</b><span>${t('精确率与召回率的调和平均','Harmonic mean of precision and recall')}</span></dd></div></dl><div class="metrics-example"><span class="tag">${t('音符级计算示例 · 非模型结果','NOTE-LEVEL EXAMPLE · NOT MODEL RESULTS')}</span><p>${t('参考 5 个音符，预测 4 个，其中 3 对符合匹配规则。','5 reference notes, 4 predictions, and 3 valid one-to-one matches.')}</p><div class="metrics-counts"><span class="metric-tp"><b>TP 3</b>${t('匹配','Matched')}</span><span class="metric-fp"><b>FP 1</b>${t('误报','Extra')}</span><span class="metric-fn"><b>FN 2</b>${t('漏检','Missed')}</span></div><p class="metrics-example-result">P = 3/4 = 0.75 · R = 3/5 = 0.60<br><strong>F1 = 6/9 ≈ 0.667</strong></p></div></div><div class="metrics-rules"><h3>${t('论文中的指标名称与匹配条件','Metric names and matching criteria')}</h3><div class="table-scroll"><table><thead><tr><th>${t('指标','METRIC')}</th><th>${t('检查什么','WHAT COUNTS')}</th></tr></thead><tbody><tr><th scope="row">Frame F1 / Frm</th><td>${t('每个时间格、每个音高是否活动。按时间—音高格统计，不按完整音符匹配。','Pitch activity at each time step. Count time–pitch cells, rather than complete note matches.')}</td></tr><tr><th scope="row">Onset F1 / OnP</th><td>${t('音高正确，且起音误差在 ±50 ms 内。','Correct pitch and onset within ±50 ms.')}</td></tr><tr><th scope="row">Offset F1 / OnPOff</th><td>${t('满足 Onset 条件，再检查结束时间：误差不超过 max(50 ms, 0.2d)。','Meet the onset criteria, plus offset error ≤ max(50 ms, 0.2d).')}</td></tr><tr><th scope="row">Multi F1</th><td>${t('满足 Offset 条件，再要求乐器类别正确；鼓点按起音匹配。','Meet the offset criteria and match the instrument class; drum hits use onset matching.')}</td></tr><tr><th scope="row">Drums F1</th><td>${t('鼓点的起音与类别匹配，不检查延音结束。','Match drum-hit onsets and classes; no sustained-note offset test.')}</td></tr></tbody></table></div><p class="metrics-rule-note">${t('d 为参考音符时长。例如 d = 1 s，结束容差为 200 ms。音符一对一匹配；多预测的重复音符仍可能成为 FP。','d is the reference-note duration: d = 1 s gives a 200 ms offset tolerance. Note matching is one-to-one; extra duplicate predictions can count as FP.')}</p></div></div><div class="metrics-protocol"><p><b>MuScriptor</b> ${t('使用 Frame、Onset、Offset、Multi 和 Drums；RL 奖励仅加总不区分乐器的前三项。','Frame / Onset / Offset / Multi / Drums. RL sums the first three, ignoring instrument identity.')}</p><p><b>Harmonica</b> ${t('使用 Frm、OnP、OnPOff，不评乐器归属。Frame 网格为 25 ms；MuScriptor 为 62.5 ms。','Frm / OnP / OnPOff, without instrument attribution. Frame grid: 25 ms; MuScriptor: 62.5 ms.')}</p><p class="metrics-scale">${t('F1 可写成 0–1 或乘以 100；0.667 = 66.7 分，不是“66.7% 音符完全正确”。跨论文还需对齐数据、匹配规则与汇总方式。','F1: 0.667 = 66.7 points, not note accuracy. Compare scores only with aligned data, matching and aggregation.')}</p></div>`,
    note:t('TP 为满足当前指标条件的一对一匹配，FP 为未匹配预测，FN 为未匹配参考。上面的计数例子只解释一个片段的音符级 F1；不能据此假设论文总分一定由全数据集 TP/FP/FN 直接汇总。Frame F1 则在时间—音高活动网格上计算精确率和召回率。Onset/OnP 不检查结束时间或乐器；Offset/OnPOff 同时要求音高、起音与结束时间，并不是只评 offset。Harmonica 的表1以 OnP 与 Frm 为主，OnPOff 也见表2与完整结果附录。原文的参数量和 xRT 属于效率指标：xRT = 音频时长 / 处理时长，越大越快，不能当作转写准确度或流式延迟。','TP counts one-to-one matches under the chosen criteria; FP counts unmatched predictions and FN unmatched references. The worked example explains note-level F1 for one excerpt, not an assumption that a paper pools counts across its full dataset. Frame F1 instead computes precision and recall over active time–pitch cells. Onset/OnP ignores offsets and instruments; Offset/OnPOff requires pitch, onset and offset, not just offset. Harmonica Table 1 emphasizes OnP and Frm, while OnPOff also appears in Table 2 and the full-results appendix. Parameter count and xRT measure efficiency: xRT = audio duration / processing time, higher is faster; neither measures transcription accuracy or establishes streaming latency.'),sources:[]},
  {id:'evaluation',chapter:'evidence',kicker:'EVALUATION METRICS',
    title:t("评测指标：音高、起止时间与乐器归属","Evaluation: pitch, note boundaries and instrument attribution"),
    lead:t('F1 综合精确率与召回率。帧级、起音、起止时间、乐器归属检查的是不同问题，不能把它们混在同一排行榜里。','F1 balances precision and recall. Frame activity, onsets, offsets and instrument attribution test different things; their scores are not interchangeable.'),
    html:`<div class="table-scroll"><table><thead><tr><th>${t('指标','METRIC')}</th><th>${t('它检查什么','WHAT IT CHECKS')}</th><th>${t('可能漏掉什么','WHAT IT CAN MISS')}</th></tr></thead><tbody><tr><td>Frame F1</td><td>${t('每一时刻有哪些音高在响','Pitch activity at each time')}</td><td>${t('重复音的起止边界','Repeated-note boundaries')}</td></tr><tr><td>Onset F1</td><td>${t('音高 + 起音（±50 ms）','Pitch + onset (±50 ms)')}</td><td>${t('结束时间与乐器','Offset and instrument')}</td></tr><tr><td>Offset F1</td><td>${t('再检查结束时间','Also checks note endings')}</td><td>${t('乐器归属','Instrument attribution')}</td></tr><tr><td>Multi F1</td><td>${t('起止、音高 + 正确乐器','Timing, pitch + instrument')}</td><td>${t('可读乐谱、主观听感','Readable notation and perceived quality')}</td></tr></tbody></table></div><p class="table-note">${t('这里采用 MT3 / MuScriptor 的解释：结束容差 max(50 ms, 参考时长的20%)；MuScriptor 的鼓点按起音评测。不同论文应先核对协议。','Here we use the MT3 / MuScriptor convention: offset tolerance max(50 ms, 20% of reference duration); MuScriptor scores drums by onset. Check each paper’s protocol.')}</p><div id="error-demo" class="error-scene"><div class="error-options"><button data-error="instrument" aria-pressed="true">${t('乐器认错','Wrong instrument')}</button><button data-error="offset" aria-pressed="false">${t('时值太长','Wrong duration')}</button><button data-error="missing" aria-pressed="false">${t('漏掉音符','Missing note')}</button></div><div class="error-roll" aria-hidden="true"><span class="error-note"></span><span id="error-pred" class="error-note pred"></span></div><div class="error-labels"><span>${t('青色：参考钢琴 C4','TEAL: reference piano C4')}</span><span>${t('橙色：假想预测','ORANGE: hypothetical prediction')}</span></div><p class="error-result mt" id="error-result" aria-live="polite"></p></div>`,
    note:t("音高与时间正确但乐器错误的预测，可以在不区分乐器的指标中匹配，却不能在 Multi F1 中匹配。F1 是精确率与召回率的调和平均，并非简单的正确音符占比。交互动画为构造示例，不是模型实验结果。","A prediction with correct pitch and timing but the wrong instrument may match an instrument-agnostic metric while failing Multi F1. F1 is the harmonic mean of precision and recall, not simply the fraction of correct notes. The interactive animation is a constructed example, not a model result."),sources:src('mt3','mu')},
  {id:'data',chapter:'evidence',kicker:'THE DATA BOTTLENECK',
    title:t("数据瓶颈：合成监督与真实录音","The data bottleneck: synthetic supervision and real recordings"),
    lead:t('要训练转录，音频与每个音符必须对齐。真正昂贵的是同时拥有真实的声音、完整的标签与可靠的时间。','Training needs audio aligned to individual notes. The expensive combination is realistic sound, complete labels and reliable timing.'),
    html:`<div class="grid two">${card('SYNTHETIC',t('从 MIDI 合成音频','Render audio from MIDI'),t('标签天然已知，可换乐器、音色、速度和音高。风险是模型学会音源库的世界，而不是实际录音的世界。','Labels are known by construction; vary instruments, sounds, tempo and pitch. The risk is learning a renderer’s world rather than recorded music.'))}${card('REAL',t('给真实录音找对应符号','Align symbols to real recordings'),t('更接近演奏、混响与混音；但改编版本、时序偏移和缺失标签都会引入监督噪声。','Captures playing, reverb and production effects. Arrangement differences, timing errors and missing labels add supervision noise.'))}</div><div class="dataset-row"><b>Slakh</b><span>${t('合成混音 + 分轨 + MIDI','Synthetic mixes + stems + MIDI')}</span><span>${t('方便研究多乐器；不能单独证明真实迁移','Useful multi-instrument supervision; real transfer still needs testing')}</span></div><div class="dataset-row"><b>MAESTRO</b><span>${t('真实钢琴录音与 MIDI 对齐','Real piano recordings aligned with MIDI')}</span><span>${t('高质量，但任务范围仍是钢琴','High quality, but restricted to piano')}</span></div><div class="dataset-row"><b>Real mixtures</b><span>${t('真实合奏与商业制作','Real ensembles and produced music')}</span><span>${t('标签完整性、来源与对齐质量都需说明','Label coverage, provenance and alignment matter')}</span></div>`+takeaway(t('下一步不是“只换一个更大的网络”，而是检验一整条数据与训练路线。','The next step is to evaluate a data-and-training pipeline, not only a larger network.')),
    note:t("数据规模与声学真实性是不同维度。MuScriptor 利用合成数据建立基础，再通过真实录音缩小分布差异。MAESTRO 说明精确音频—MIDI 对齐的价值，但其钢琴范围不能替代多乐器混音评测。","Scale and acoustic realism are distinct dimensions. MuScriptor uses synthetic data as a foundation and real recordings to address distribution differences. MAESTRO illustrates the value of precise audio–MIDI alignment, but its piano scope does not replace evaluation on multi-instrument mixtures."),sources:[...src('slakh','mu'),{label:'MAESTRO · dataset paper',url:'https://arxiv.org/abs/1810.12247'}]},
  {id:'harmonica',chapter:'harmonica',kicker:'HARMONICA · LONGSHEN OU ET AL. · 2026',
    title:t('Harmonica：跨乐器泛化的逐帧转录','Harmonica: frame-level transcription across instruments'),
    lead:t('Longshen Ou、Héctor Martel、Joe Hennessy-Priest、Taemin Cho · BandLab。一个模型转录不同有音高乐器的独奏或独立分轨，可处理复音；输出音高与起止时间，不预测乐器归属。','Longshen Ou, Héctor Martel, Joe Hennessy-Priest and Taemin Cho · BandLab. One model transcribes solos or isolated stems across pitched instruments, including polyphony. Outputs contain pitch and timing, without instrument labels.'),
    paperLinks:paperAccess('2609.04640v1',['3.3','S3.SS3'],3),
    html:paperFigure({id:'figure-harmonica-model',image:'assets/papers/harmonica-architecture.png',title:t('Figure 2 · CQT → 谐波卷积 → 音符','Figure 2 · CQT → harmonic convolution → notes'),alt:t('Harmonica原文图2：CQT输入经前端和重复的谐波卷积主干，进入起音、持续和结束三个头；结束头仅提供辅助监督','Original Harmonica Figure 2: CQT features pass through a frontend and repeated harmonic trunk blocks to onset, sustain and offset heads; the offset head supplies auxiliary supervision'),paper:'2609.04640v1',anchor:'S3.F2',page:3,number:2,credit:t('Ou et al. (2026), Fig. 2 · 原文PDF图像摘录，未重绘；版权归原权利人。','Ou et al. (2026), Fig. 2 · Figure excerpt from the original PDF, not redrawn; copyright remains with the original rights holders.'),steps:[
      [t('前端：对齐频率与音高','Frontend: align frequency with pitch'),t('16 kHz音频 → CQT（每半音3个bin、32 ms帧间隔）→ 两个ResNet块；频率下采样后每半音对应一个位置。','16 kHz audio → CQT (3 bins/semitone, 32 ms frames) → two ResNet blocks. Frequency downsampling leaves one position per semitone.')],
      [t('主干：多层重复谐波聚合','Trunk: repeat harmonic aggregation'),t('每个Trunk Block结合Harmonic Conv与ResNet。右上角小图展示同一候选基频与高、低频相关位置的联系。','Each trunk block combines Harmonic Conv and ResNet. The upper-right inset links a candidate fundamental to related higher and lower frequencies.')],
      [t('输出：逐帧预测再解码','Output: predict frames, then decode'),t('三个FGLSTM头学习起音、持续与结束。实际解码只使用起音和持续预测；Offset Head仅作辅助监督。','Three FGLSTM heads learn onset, sustain and offset. Decoding uses only onset and sustain; the offset head provides auxiliary supervision.')]
    ]})+takeaway(t('Instrument-agnostic：适用于不同乐器的同一个转录器。多乐器混音转录还需要恢复“每个音符属于谁”。','Instrument-agnostic: one transcriber usable across instruments. Transcribing multi-instrument mixtures additionally requires assigning notes to their sources.')),
    note:t('版本为2026-09-04 arXiv v1，标注投稿ICASSP 2027，未据此声称已接收。§3.1定义输入为身份未知的单乐器音频；URMP和Slakh的实验使用独立分轨、排除混音和Slakh鼓轨。单乐器可复音，不能把这个设定误读成单音高追踪。图中Pitch Head输出持续活动；Offset Head没有连接到Decode。','Reviewed version: arXiv v1, 2026-09-04, marked submitted to ICASSP 2027, not confirmed accepted. §3.1 defines an unknown single instrument; URMP and Slakh experiments use stems, excluding mixtures and Slakh drums. A single instrument can be polyphonic. The diagram’s Pitch Head predicts sustained activity; the Offset Head does not feed Decode.'),sources:src('harmonica')},
  {id:'harmonic-convolution',chapter:'harmonica',kicker:'HARMONICA · THE CORE MECHANISM',
    title:t('谐波卷积：这个频率是基频，还是别的音的泛音？','Harmonic convolution: fundamental or someone else’s overtone?'),
    lead:t('对候选频率 f，同时查看整数倍与分频位置的证据。核心操作是沿频率轴平移特征、按通道拼接，再用1×1卷积学习聚合；这一过程在多个网络深度重复。','For a candidate frequency f, inspect multiples and submultiples. Shift frequency features, concatenate channels, and learn their aggregation with a 1×1 convolution. Repeat this operation at several network depths.'),
    paperLinks:paperAccess('2609.04640v1',['3.4','S3.SS4'],3),
    html:`<figure class="harmonic-context"><figcaption>${t('阅读图2右上角：以下以 f = 220 Hz 作概念示意','Reading the inset in Figure 2: a conceptual example with f = 220 Hz')}</figcaption><div class="harmonic-bins"><div><span>f / 2</span><b>110 Hz</b><p>${t('若低处也有基频证据，220 Hz可能是它的泛音。','Lower-frequency evidence suggests 220 Hz might be an overtone.')}</p></div><div class="candidate"><span>${t('候选基频 f','CANDIDATE f')}</span><b>220 Hz</b><p>${t('这个位置是否应当产生一个音符？','Should this position represent a note?')}</p></div><div><span>2f · 3f · …</span><b>440 · 660 Hz</b><p>${t('高处的谐波结构为220 Hz候选提供支持。','Higher harmonics can support the 220 Hz candidate.')}</p></div></div><p class="table-note">${t('原创说明图，仅选部分关系；不表示真实频谱幅度或全部偏移。证据由网络学习组合，不是固定的“有峰就有音符”规则。','Original schematic showing selected relations, not measured amplitudes or every offset. The network learns to combine evidence; peaks do not deterministically imply notes.')}</p></figure>`+nodes([[t('沿频率平移','Shift frequency features'),t('7个谐波 + 7个分频位置','7 harmonic + 7 subharmonic positions')],[t('按通道拼接','Concatenate channels'),t('M份特征 → C × M个通道','M copies → C × M channels')],['1 × 1 Conv',t('C × M → C，再接ResNet','C × M → C, then ResNet'),'focus']])+`<div class="table-scroll mt"><table><thead><tr><th>${t('表2节选：谐波聚合','Table 2 excerpt: aggregation')}</th><th>OnPOff F1</th><th>Frame F1</th></tr></thead><tbody><tr><td>${t('无谐波聚合','No harmonic aggregation')}</td><td>0.635</td><td>0.823</td></tr><tr><td>${t('单层 shift-and-aggregate','Single-depth shift-and-aggregate')}</td><td>0.731</td><td>0.867</td></tr><tr><td><b>${t('多层 shift-and-aggregate','Multi-depth shift-and-aggregate')}</b></td><td><b>0.745</b></td><td><b>0.876</b></td></tr><tr><td>${t('多层 HD-Conv','Multi-depth HD-Conv')}</td><td>0.745</td><td>0.877</td></tr></tbody></table></div><p class="table-note">${t('Medium变体 · 留出开发集 · 3个随机种子的均值 · F1为0–1。','Medium variants · held-out development set · means over 3 random seeds · F1 scale 0–1.')} <a href="https://arxiv.org/html/2609.04640v1#S4.T2" target="_blank" rel="noopener noreferrer">${t('原文表2','Original Table 2')} ↗</a> · <a href="https://arxiv.org/pdf/2609.04640v1#page=4" target="_blank" rel="noopener noreferrer">${t('PDF第4页','PDF page 4')} ↗</a></p>`+takeaway(t('两个贡献要分开：多层聚合改善预测；shift-and-aggregate减少中心位置的重复参数，较HD-Conv节省28.5%的谐波层参数，效果相近。','Separate two contributions: aggregation at multiple depths improves prediction; shift-and-aggregate removes redundant center weights, saving 28.5% of harmonic-layer parameters versus HD-Conv with similar accuracy.')),
    note:t('“多深度”指在不同特征层反复做谐波聚合，不是把多个音频分辨率简单拼在一起。聚合后经过归一化、残差连接与ReLU，再进入ResNet。表2中多层相对单层的OnPOff提升为0.014，即1.4个F1点；28.5%是谐波层参数降幅，不是整个模型。分频证据可能提示当前峰属于更低音，但复音下仍有歧义，模型必须联合解释。','Multi-depth means harmonic aggregation at successive feature layers, not simply concatenating audio resolutions. Aggregation is followed by normalization, a residual connection and ReLU before ResNet. Multi-depth improves OnPOff by 0.014, or 1.4 F1 points, over single-depth. The 28.5% reduction concerns harmonic layers, not the entire model. Subharmonic evidence can suggest a lower fundamental, but polyphony still makes the interpretation ambiguous.'),sources:src('harmonica')},
  {id:'harmonica-results',chapter:'harmonica',kicker:'HARMONICA · EVIDENCE & COMPARISON',
    title:t('Harmonica：准确率、规模与评测边界','Harmonica: accuracy, scale and evaluation scope'),
    lead:t('模型从26.3K参数的nano扩展到15.1M的x-large。阅读结果时，要区分开发集曲线、各测试集分数，以及指定硬件上的推断速度。','The family ranges from the 26.3K-parameter nano to the 15.1M x-large. Distinguish development-set curves, individual test-set scores and inference speed on specified hardware.'),
    paperLinks:paperAccess('2609.04640v1',['4.2','S4.SS2'],4),
    html:paperFigure({id:'figure-harmonica-scale',image:'assets/papers/harmonica-size-performance.svg',title:t('Figure 1 · 参数规模与开发集Frame F1','Figure 1 · Model size and development-set Frame F1'),alt:t('Harmonica原文图1：横轴为模型参数量，纵轴为留出多来源开发集的Frame F1，比较Harmonica系列与基线','Original Harmonica Figure 1: parameter count versus Frame F1 on the held-out multi-source development set, comparing the Harmonica family with baselines'),paper:'2609.04640v1',anchor:'S1.F1',page:1,number:1,credit:t('Ou et al. (2026), Fig. 1 · 原文SVG原样转载；版权归原权利人。','Ou et al. (2026), Fig. 1 · Original SVG reproduced unchanged; copyright remains with the original rights holders.'),steps:[
      [t('先读坐标','Read the axes'),t('横轴为对数尺度的参数量，纵轴是开发集Frame F1；这张图不直接衡量推断速度，也不是8个测试集的平均分。','The axes show parameters on a log scale and development Frame F1, not runtime or an average of the eight test sets.')],
      [t('规模与效率分别看','Separate scale from speed'),t('Nano的开发集Frame F1为0.796。表1另报告RTX 4090速度：nano 1622.5×、medium 848.5×实时；手机表现需看附录A。','Nano achieves 0.796 development Frame F1. Table 1 separately reports RTX 4090 speeds: nano 1622.5× and medium 848.5× real time; mobile results are in Appendix A.')],
      [t('检验外部泛化','Check generalization'),t('X-large在域内测试集的Frame F1领先；域外MAPS上，HPPNet-sp更高。不同音色与评测分布仍会改变结论。','X-large leads Frame F1 on in-domain test sets; HPPNet-sp scores higher on out-of-domain MAPS. Timbre and evaluation distribution still matter.')]
    ]})+`<div class="callout">${t('<b>与MuScriptor对照时：</b>Harmonica评估单乐器/分轨、无乐器归属；其中MuScriptor基线是已发布的medium（主表约306M），不是后文1.3B混音实验。11个基线中8个重训；MT3、Basic Pitch、MuScriptor使用已发布权重。不能把两篇论文的分数直接并排排名。','<b>Comparison with MuScriptor:</b> Harmonica evaluates isolated instruments/stems without attribution. Its MuScriptor baseline is the released medium (~306M in the main table), not the later 1.3B mixture experiment. Eight of eleven baselines are retrained; MT3, Basic Pitch and MuScriptor use released weights. Scores from the two papers do not form a common ranking.')}</div>${link('https://www.oulongshen.xyz/amt',t('作者演示与音频案例','Author demos and audio examples'))}`,
    note:t('这篇工作的意义在于显式谐波先验和准确率—计算成本关系。若要把它用于多乐器混音，需要额外处理音符归属并在混音上验证；不能从分轨结果直接外推。论文中的速度是xRT=音频时长/处理时长，更高更快，并不代表流式延迟。主表MuScriptor约306M、附录306.5M，与本网站后续论文的1.3B命名分开。','The contribution concerns explicit harmonic priors and the accuracy–compute trade-off. Using it for multi-instrument mixtures would require attribution and mixture evaluation. xRT is audio duration divided by processing time; it does not establish streaming latency. The MuScriptor baseline is ~306M in the main table and 306.5M in the appendix, distinct from the subsequent paper’s 1.3B label.'),sources:src('harmonica','mu')},
  {id:'muscriptor',chapter:'muscriptor',kicker:'MUSCRIPTOR · ISMIR 2026',
    title:t("MuScriptor：面向真实音乐的多乐器转录","MuScriptor: multi-instrument transcription of real music"),
    lead:t('Rouard、Krause 等 · Kyutai × Mirelo × IRCAM。核心是仅解码器 Transformer，以及“合成预训练 → 真实微调 → 强化学习后训练”的完整路线。','Rouard, Krause et al. · Kyutai × Mirelo × IRCAM. A decoder-only Transformer paired with synthetic pretraining, real-audio fine-tuning and reinforcement post-training.'),
    paperLinks:paperAccess('2607.08168v2',['1','S1'],1),
    html:`<div class="grid three">${card('01 / PRETRAIN',t('建立音频—事件映射','Learn audio-to-event mappings'),t('大规模 MIDI 渲染，让模型建立音频到事件的基础。','Large-scale MIDI rendering builds the audio-to-event foundation.'))}${card('02 / ADAPT',t('再适应真实录音','Adapt to real recordings'),t('真实音乐提供更丰富的音色、演奏和制作方式。','Real music brings richer timbres, performances and production styles.'),'accent')}${card('03 / REFINE',t('用音符指标做后训练','Refine using note metrics'),t('对同一片段生成多个答案，奖励相对更好的候选。','Generate several answers to a clip and reward relatively better candidates.'))}</div><div class="callout">${t('<b>阅读版本：</b>arXiv v2，2026-08-03，ISMIR 2026 camera-ready。以下数字沿用论文的“1.3B”命名；当前代码仓库的 large 写作“1.4B”，不混用。','<b>Version reviewed:</b> arXiv v2, 2026-08-03, ISMIR 2026 camera-ready. Results retain the paper’s “1.3B” label; the current repository calls its large model “1.4B”. These labels are kept separate.')}</div>${link('https://arxiv.org/abs/2607.08168v2',t('打开论文','Read the paper'))}${link('https://muscriptor.kyutai.org/',t('官方体验','Official app'))}${link('https://github.com/muscriptor/muscriptor',t('官方代码','Official code'))}`,
    note:t("MuScriptor 的核心是仅解码器架构与分阶段数据、训练策略的结合。理解其贡献需要同时考察输入输出表示、训练语料、乐器条件、实验协议与表示边界，不能仅依据某个网络模块或单一分数判断。","MuScriptor combines a decoder-only architecture with staged data and training strategies. Its contribution is assessed through input and output representations, training corpora, instrument conditions, experimental protocols and representational limits, rather than a single module or score."),sources:src('mu')},
  {id:'architecture',chapter:'muscriptor',kicker:'MUSCRIPTOR · ARCHITECTURE',
    title:t("模型架构：音频前缀与自回归事件解码","Architecture: audio prefixes and autoregressive event decoding"),
    lead:t('把一段音乐的频谱投影为向量，与可选的乐器条件一起送入仅解码器 Transformer，然后逐个预测音乐事件。','Project a music spectrogram into vectors, combine it with optional instrument conditions, and let a decoder-only Transformer predict musical events.'),
    paperLinks:paperAccess('2607.08168v2',['3.2','S3.SS2'],4),
    html:`<div class="source-notice">${t('<b>结构示意的依据：</b>原论文没有单独的网络架构图。下图根据 §3.2 与公开词表代码重构；可通过上方入口直接对照原文第4页。','<b>Source of this schematic:</b> the paper has no standalone network architecture figure. The flow below is reconstructed from §3.2 and the released tokenizer; use the links above to compare it with PDF page 4.')}</div>`+nodes([[t('5 秒音频','5-second audio'),'16 kHz · mono'],[t('Mel 频谱','Mel spectrogram'),'512 bins · 100 frames/s'],[t('前缀','Prefix'),t('音频向量 + 乐器集合','Audio vectors + instrument set'),'focus']])+nodes([['Transformer',t('仅解码器 · 自回归','Decoder-only · autoregressive'),'focus'],[t('事件流','Event stream'),t('时间 / 音高 / 乐器 / 开关音 / 鼓点','Time / pitch / program / on–off / drums')],['MIDI',t('分段连接后的音符','Notes joined across chunks')]])+`<div class="grid two mt">${card(t('表示','REPRESENTATION'),t('36 个乐器子组','36 instrument subgroups'),t('将128种 MIDI program 归为 MT3_FULL_PLUS 子组，另有鼓点事件。乐器类别不等于演奏者身份。','128 MIDI programs map to MT3_FULL_PLUS subgroups, plus drum events. An instrument class is not a performer identity.'))}${card(t('解码','DECODING'),t('选下一个最可能的事件','Choose the next likely event'),t('推理用 argmax；训练用 teacher forcing + 交叉熵。跨片段持续音需要 tie 信息。当前词表中的 velocity 是开关音状态，并非细粒度力度。','Argmax inference; teacher forcing and cross entropy in training. Tie information handles sustained notes. The released vocabulary uses velocity as an on/off state, not expressive dynamics.'))}</div><p class="table-note">${t('根据论文§3.2与公开词表代码绘制的概念流程；不是论文原图。','Conceptual reconstruction from §3.2 and the released tokenizer; not an original paper figure.')}</p>`,
    note:t("MT3 使用编码器—解码器结构；MuScriptor 将投影后的音频作为仅解码器模型的前缀。该流程不要求先进行音源分离，也不是自然语言生成。5 秒约对应 500 帧，实际张量长度可能受填充影响。","MT3 uses an encoder–decoder, whereas MuScriptor supplies projected audio as a prefix to a decoder-only model. The pipeline does not require source separation and does not generate natural language. Five seconds corresponds to roughly 500 frames; padding can affect the exact tensor length."),sources:[...src('mu'),{label:'Tokenizer · pinned source',url:'https://github.com/muscriptor/muscriptor/blob/7f213afecf23bd6a1b8672aa223690ee9807cefb/muscriptor/tokenizer/notes.py'}]},
  {id:'training',chapter:'muscriptor',kicker:'MUSCRIPTOR · TRAINING STRATEGY',
    title:t("三阶段训练：合成预训练、真实微调与后训练","Three-stage training: synthetic pretraining, real adaptation and refinement"),
    lead:t('模型先拥有大量精确标签，再接触真实混音，最后用少量人工核验数据优化预测质量。规模与标注质量在不同阶段发挥作用。','Start with many precise labels, adapt to real mixtures, then refine predictions with a small, manually checked set. Scale and label quality play different roles.'),
    paperLinks:paperAccess('2607.08168v2',['3.4','S3.SS4'],4),
    html:`<div class="grid three">${card('SYNTH',t('约 145 万 MIDI','~1.45M MIDI files'),t('超过250个 soundfont；在线改变音高、速度、力度与乐器，再渲染与增强。','Over 250 soundfonts, with on-the-fly pitch, tempo, velocity and instrument variation, rendering and augmentation.'))}${card('REAL',t('约 17 万真实录音','~170K real recordings'),t('超过1.1万小时。依靠小节线插值或色度/起音特征的DTW对齐，并剔除差的匹配。','Over 11K hours. Align using bar-line interpolation or chroma/onset DTW, and reject poor matches.'),'accent')}${card('RL',t('300 首人工核验曲目','300 quality-checked tracks'),t('每段采样8个候选，与参考音符比较。奖励来自指标，不是人类偏好模型。','Sample eight candidates per clip and compare them with reference notes. Rewards are metrics, not a human-preference model.'))}</div><div class="equation">reward = F1<sub>onset</sub> + F1<sub>frame</sub> + F1<sub>offset</sub></div>`+nodes([[t('同一片段','Same clip'),t('采样8份转录','Sample 8 transcriptions')],[t('比较奖励','Compare rewards'),t('组内归一化 → 相对优势','Normalize within group → advantage')],[t('更新模型','Update policy'),t('鼓励相对更好的候选','Favor relatively better answers'),'focus']])+`<div class="callout">${t('<b>准确称呼：</b>GRPO-like 的 REINFORCE 更新；没有裁剪重要性比，也没有对冻结参考模型的 KL 惩罚。奖励不区分乐器，不是 Multi F1，也不是 RLHF。','<b>Precise description:</b> GRPO-like REINFORCE updates, without clipped importance ratios or a KL penalty to a frozen reference policy. The reward is instrument-agnostic; it is not Multi F1 or RLHF.')}</div>`,
    note:t("合成数据提供大规模精确标签，真实数据缩小域差异，人工核验数据用于后训练。组相对奖励比较同一片段的 8 个候选与参考标注。主表支持后训练带来的收益，但不能单独区分优化算法与高质量数据子集的贡献。","Synthetic data supplies large-scale precise labels, real data addresses the domain gap, and checked data supports post-training. Group-relative rewards compare eight candidates for the same clip against reference annotations. The main table supports a post-training gain but does not isolate the optimization algorithm from the contribution of the high-quality subset."),sources:src('mu')},
  {id:'pretraining',chapter:'muscriptor',kicker:'MUSCRIPTOR · PRETRAINING ABLATION',
    title:t('原文消融：合成预训练在何时最有帮助','Original ablation: when does synthetic pretraining help most?'),
    lead:t('图4控制真实数据的使用比例，对比“有合成预训练”与“无合成预训练”。它直接检验合成数据在真实标签稀缺时的作用。','Figure 4 varies the fraction of real training data and compares models with and without synthetic pretraining. It directly examines the role of synthetic data when real labels are scarce.'),
    paperLinks:paperAccess('2607.08168v2',['4.1.1','S4.SS1.SSS1'],5),
    html:paperFigure({id:'figure-mu-pretraining',image:'assets/papers/muscriptor-pretraining-figure4.png',title:t('Figure 4 · 真实数据规模与合成预训练','Figure 4 · Real-data scale and synthetic pretraining'),alt:t('MuScriptor原文图4：五项指标随真实训练数据比例的变化，蓝色为有合成预训练，红色为无合成预训练','Original MuScriptor Figure 4: five metrics versus real training-data fraction, blue with synthetic pretraining and red without'),paper:'2607.08168v2',anchor:'S3.F4',page:5,number:4,credit:t('Rouard et al. (2026), Fig. 4 · CC BY 4.0 · 从PDF第5页裁取，保留原始图注，未改绘数据。','Rouard et al. (2026), Fig. 4 · CC BY 4.0 · Cropped from PDF page 5 with the original caption; data not redrawn.'),steps:[
      [t('先对齐坐标与图例','Read the axes and legend'),t('横轴为真实训练数据比例；五个面板对应不同评价指标。蓝线先做合成预训练，红线只用真实数据训练。','The x-axis is the fraction of real training data; panels use different metrics. Blue includes synthetic pretraining; red trains on real data alone.')],
      [t('少量真实数据：差距显著','Limited real data: a large gap'),t('在1%真实数据下，Offset F1 从9.9提升到33.4。合成预训练为真实域适应提供了较强起点。','At 1% real data, Offset F1 rises from 9.9 to 33.4. Synthetic pretraining provides a strong starting point for adaptation.')],
      [t('全量真实数据：差距缩小','Full real data: a smaller gap'),t('100%时，同一指标为41.0与42.3。本图使用CFG=2且不含RL，不能与主表CFG=1的最终成绩混用。','At 100%, the same metric is 41.0 versus 42.3. This figure uses CFG=2 without RL, unlike the final CFG=1 results in the main table.')]
    ]}),
    note:t('先讲对照变量：真实数据比例与合成预训练。再选同一指标比较两个数据规模，避免跨面板直接比较数值。图4说明预训练收益随真实数据量变化；它不是RL消融，也不能单独证明架构优于其他方法。','Identify the two variables: real-data fraction and synthetic pretraining. Compare the same metric at two scales rather than comparing values across panels. Figure 4 shows that pretraining gains depend on real-data availability; it is neither an RL ablation nor an isolated architecture comparison.'),sources:src('mu')},
  {id:'conditioning',chapter:'muscriptor',kicker:'MUSCRIPTOR · CONTROL & CONTINUITY',
    title:t("乐器条件与跨片段一致性","Instrument conditioning and cross-chunk consistency"),
    lead:t('乐器条件可以让跨片段的身份更稳定，也能只请求一部分声部。但评测时给出真实乐器列表，与完全盲转录不是同一种设定。','Instrument conditions help stabilize identities across chunks and request selected parts. Providing the reference instrument list during evaluation differs from fully blind transcription.'),
    paperLinks:paperAccess('2607.08168v2',['4.1.3','S4.SS1.SSS3'],6),
    html:`<div class="grid two">${card('WITHOUT CONDITIONS',t('同时推断“谁”与“什么音”','Infer both “who” and “which notes”'),t('模型从音频自行推断乐器，可能在近似音色之间切换身份。支持无条件使用，不代表主表就是无条件评测。','Infer instruments from audio; similar timbres may cause identity changes. Unconditioned use is supported, but the headline table is not that setting.'))}${card('WITH CONDITIONS',t('先给一个乐器集合','Supply an instrument set'),t('例如 {钢琴，贝斯，鼓}。这是整首曲目的集合，不要求每种乐器在每个5秒片段都发声。','For example {piano, bass, drums}. The set applies to the whole track; a listed instrument may be silent within a five-second clip.'),'accent')}</div><div class="chips"><span class="chip orange">Piano</span><span class="chip teal">Bass</span><span class="chip blue">Drums</span><span class="chip">→ instrument embeddings</span><span class="chip">→ decoder prefix</span></div><div class="callout">${t('<b>论文的条件消融：</b>真实数据单独训练、CFG=2 时，Multi F1 从无条件的38.7变为有条件的40.5。这是单独消融，不是最终RL模型的成绩。','<b>Conditioning ablation:</b> with real-only training and CFG=2, Multi F1 is 38.7 without conditions and 40.5 with them. This separate ablation is not the final RL model.')}</div>`+takeaway(t('“有条件”不是作弊，但条件必须公开，比较才能公平。','Conditioning is a valid setting; fairness requires making that setting explicit.')),
    note:t("已知乐器集合会缩小推断空间。论文默认结果使用参考标注中的乐器集合，因此与盲转录设定不同。CFG=1 表示不进行引导放大；最终 RL 模型无需 CFG=2 的额外前向计算即可获得主表最佳 Multi F1。","A known instrument set narrows the inference space. Default paper results use reference-derived instrument sets and therefore differ from blind transcription. CFG=1 means no guidance amplification; the final RL model obtains its best reported Multi F1 without the additional forward computation required by CFG=2."),sources:src('mu')},
  {id:'results',chapter:'muscriptor',kicker:'MUSCRIPTOR · EMPIRICAL RESULTS',
    title:t("实验结果：训练阶段与跨数据集表现","Results: training stages and cross-dataset performance"),
    lead:t('下面只比较同一张论文表中的训练阶段。它支持这条训练路线的价值，但没有把数据、规模与架构的贡献完全拆开。','Compare training stages within the same paper table. The evidence supports the training recipe, but does not fully isolate data, scale and architecture.'),
    paperLinks:paperAccess('2607.08168v2',['4','S4'],5),
    html:`<div class="callout"><b>${t('左侧阶段图协议（请与数字一起读）','LEFT: STAGE-COMPARISON PROTOCOL')}</b><br>${t('作者内部 DTest：372首 · 论文1.3B模型 · 参考乐器条件 · CFG=1 · 同乐器同音高重叠参考音符经过过滤。分数为作者报告，未独立复现。','Internal DTest: 372 tracks · paper 1.3B model · reference instrument conditioning · CFG=1 · overlapping same-instrument/same-pitch reference notes filtered. Author-reported; not independently reproduced.')}</div><div class="grid two mt"><div class="card"><span class="tag">MULTI F1 · 0–100</span><div class="bars mt"><div class="bar-row"><span>${t('仅合成','Synthetic only')}</span><div class="bar-track"><div class="bar-fill" style="width:15.2%"></div></div><strong>15.2</strong></div><div class="bar-row"><span>${t('+ 真实微调','+ Real fine-tuning')}</span><div class="bar-track"><div class="bar-fill" style="width:41.7%"></div></div><strong>41.7</strong></div><div class="bar-row"><span>${t('+ RL后训练','+ RL post-training')}</span><div class="bar-track"><div class="bar-fill" style="width:48.2%"></div></div><strong>48.2</strong></div></div><p class="table-note">${t('重绘自表1；条形轴为0–100。增量分别为 +26.5 与 +6.5 个F1点。YourMT3+ noPS参考基线：21.9；训练规模与可用条件不同，不能只归因于架构。','Redrawn from Table 1; bar scale 0–100. Gains: +26.5 and +6.5 F1 points. YourMT3+ noPS reference: 21.9. Training scale and conditioning differ, so this is not an architecture-only comparison.')}</p></div><div class="card"><span class="tag">${t('公开数据集 · 表2 / CFG=1','PUBLIC DATASETS · TABLE 2 / CFG=1')}</span><div class="table-scroll mt"><table><thead><tr><th>Multi F1</th><th>YourMT3+</th><th>MuScriptor</th></tr></thead><tbody><tr><td>RWC-P</td><td>19.1</td><td>25.6 ↑</td></tr><tr><td>PHENICX</td><td>12.2</td><td>25.7 ↑</td></tr><tr><td>RWC-C</td><td>40.5</td><td>36.0 ↓</td></tr><tr><td>RWC-R</td><td>23.1</td><td>20.3 ↓</td></tr></tbody></table></div><p class="table-note">${t('右侧为外部数据集表2：1.3B、参考乐器条件、CFG=1。选取改善与退步案例，完整8个数据集见文献展开项。','Right: external datasets in Table 2; 1.3B, reference instrument conditioning, CFG=1. Selected gains and regressions; all eight datasets are in the expanded paper entry.')}</p></div></div>`+takeaway(t('合成预训练是起点；真实微调决定了主表中最明显的迁移收益。','Synthetic pretraining provides a starting point; real fine-tuning delivers the largest stage gain here.')),
    note:t("主表中，真实微调对应最大的阶段增益，RL 后训练进一步提高 Multi F1。图4还显示：在1%真实数据下，合成预训练使 Offset F1 从9.9提高到33.4；全量时从41.0提高到42.3（CFG=2，无RL）。合成预训练在真实标签稀缺时尤其重要。","Real fine-tuning produces the largest stage gain in the main table, and RL post-training further improves Multi F1. Figure 4 shows synthetic pretraining raising Offset F1 from 9.9 to 33.4 at 1% real data and from 41.0 to 42.3 at full scale (CFG=2, no RL). Synthetic pretraining is especially valuable when real labels are scarce."),sources:src('mu')},
  {id:'qualitative',chapter:'muscriptor',kicker:'MUSCRIPTOR · QUALITATIVE EVIDENCE',
    title:t('原文案例：训练阶段如何改变音符错误','Original example: how training stages change note errors'),
    lead:t('图1在同一吉他片段上对照 YourMT3+ 与 MuScriptor 的不同训练阶段。结合漏检和误报的位置，可以把汇总指标还原为具体的音符错误。','Figure 1 compares YourMT3+ with successive MuScriptor training stages on one guitar excerpt. The locations of missed and false notes connect aggregate metrics to concrete transcription errors.'),
    paperLinks:paperAccess('2607.08168v2',['1','S1'],2),
    html:paperFigure({id:'figure-mu-notes',image:'assets/muscriptor-figure1.png',title:t('Figure 1 · 吉他音符转录对照','Figure 1 · Guitar-note transcription comparison'),alt:t('MuScriptor论文图1：四行分别为YourMT3+、合成训练、加真实微调、加RL；蓝色正确，绿色漏检，橙色误报','MuScriptor Figure 1: YourMT3+, synthetic-only, real-adapted and RL-refined results; blue correct, green missed, orange false notes'),paper:'2607.08168v2',anchor:'S1.F1',page:2,number:1,credit:t('Rouard et al. (2026), Fig. 1 · CC BY 4.0 · 原样转载。','Rouard et al. (2026), Fig. 1 · CC BY 4.0 · Reproduced unchanged.'),steps:[
      [t('从上到下：辨认对照','Top to bottom: identify comparisons'),t('依次为 YourMT3+、仅合成训练、加入真实微调、再加入RL。横轴为时间，纵轴为音高。','Rows show YourMT3+, synthetic-only training, real-data adaptation, then RL refinement. Time is horizontal and pitch vertical.')],
      [t('按颜色：定位错误','By color: locate errors'),t('蓝色 TP 表示匹配音符；绿色斜线 FN 表示参考中有但被漏掉；橙色斜线 FP 表示模型多预测的部分。','Blue TP marks matched notes; green hatched FN marks missed reference notes; orange hatched FP marks false predictions.')],
      [t('逐段看边界与持续时间','Compare boundaries and durations'),t('可对照10–15秒与25–30秒区域观察误报和持续时间差异。单一案例帮助解释错误类型，总体结论仍应依据表1、表2。','Compare 10–15 s and 25–30 s for false predictions and duration differences. One example explains error types; Tables 1 and 2 support aggregate conclusions.')]
    ]})+`<p class="table-note">${t('点击图片可放大，或直接打开原文PDF第2页。原图中的粗竖线对应分段边界。','Enlarge the figure or open PDF page 2 directly. Thick vertical lines mark segment boundaries in the original figure.')}</p>`,
    note:t('这个案例便于观察真实微调和后训练后长音误报、漏音与边界的变化，但属于作者选择的定性示例。不要从单个片段推断所有乐器和数据集的效果。不同模型的分段长度也不同。','This author-selected qualitative example helps examine false sustained notes, missed notes and boundaries after adaptation and refinement. It does not establish performance for every instrument or dataset. Segment lengths also differ between models.'),sources:src('mu')},
  {id:'limits',chapter:'muscriptor',kicker:'MUSCRIPTOR · LIMITATIONS',
    title:t("局限：表示能力、评测设定与可复现性","Limitations: representation, evaluation and reproducibility"),
    lead:t('把模型变得更有用，不等于问题已经解决。评测协议、表示能力和可复现性，仍然影响我们如何解读结果。','A more useful model does not mean the task is solved. Evaluation choices, representational limits and reproducibility still shape the interpretation.'),
    paperLinks:paperAccess('2607.08168v2',['4.2.3','S4.SS2.SSS3'],6),
    html:`<div class="grid three">${card('REPRESENTATION',t('同乐器、同音高的重叠','Same-instrument, same-pitch overlaps'),t('每个(乐器,音高)只能同时表示一个活动音符。保留这些冲突参考音符后，最终 Multi F1 从48.2降至42.0。','Only one active note per (instrument, pitch) pair. Retaining conflicting reference notes lowers final Multi F1 from 48.2 to 42.0.'),'accent')}${card('REPRODUCIBILITY',t('开放权重 ≠ 开放全部训练','Open weights ≠ open training data'),t('真实训练语料是内部数据。代码MIT；权重CC BY-NC 4.0。可以运行模型，不等于可以完整复现数据与训练。','The real training corpus is internal. Code is MIT; weights are CC BY-NC 4.0. Running inference does not reproduce the full data and training pipeline.'))}${card('USEFULNESS',t('音符准确性与乐谱可用性','Note accuracy and score usability'),t('5秒上下文、长尾音色、跨段连续性仍有挑战；MIDI之后还要处理量化、声部和记谱。','Five-second context, rare timbres and continuity remain challenges. MIDI still needs quantization, voice assignment and notation decisions.'))}</div><div class="callout">${t('<b>待验证的对照：</b>用同样300首高质量数据，只做监督微调会怎样？论文主表没有给出这个严格匹配的对照，因此不能把全部收益只归因于RL算法。','<b>A missing controlled comparison:</b> what if the same 300 checked tracks were used only for supervised fine-tuning? The main table lacks that matched control, so the entire gain cannot be attributed solely to the RL algorithm.')}</div>${link('https://kyutai.org/blog/2026-07-10-muscriptor/',t('官方音频比较','Official audio comparisons'))}`,
    note:t("同乐器、同音高的重叠音符暴露了事件表示的上限，并影响评测结果。论文的1.3B与当前软件 large 的1.4B命名需要区分；软件提供乐谱导出，也不等于论文中的模型直接预测乐谱结构。官方音频案例可用于补充定量结果。","Overlapping notes with the same instrument and pitch expose limits of the event representation and affect evaluation. The paper’s 1.3B label differs from the current software’s 1.4B large label. Software score export does not imply that the paper’s model directly predicts notation structure. Official audio examples complement the quantitative results."),sources:[...src('mu'),{label:'Official repository · license / exports',url:'https://github.com/muscriptor/muscriptor'}]},
  {id:'frontiers',chapter:'discussion',kicker:'THE CURRENT LANDSCAPE',
    title:t("当前研究方向","Current research directions"),
    lead:t('最新方向没有收敛到一个“万能模型”。预训练表征、推理效率和直接记谱，分别回答不同问题。','Recent work does not converge on a single universal model. Pretrained representations, efficient inference and direct notation address different questions.'),
    html:`<div class="grid three">${card('AMT CHALLENGE · 2026',t('预训练音乐表征','Pretrained music representations'),t('2025挑战赛报告中的MIROS使用MusicFM与乐器条件多解码器。测试是76段、至多3种乐器的合成短曲，不能外推到密集商业混音。','MIROS in the 2025 challenge report uses MusicFM with instrument-conditioned decoders. Its 76 synthesized test pieces have at most three instruments—not dense commercial mixes.'))}${card('HARMONICA · 2026',t('轻量、不区分乐器','Lightweight, instrument-agnostic'),t('Longshen Ou等：面向不同乐器独奏/分轨的多深度谐波卷积。模型架构、机制与实验已在Harmonica专章展开。','Longshen Ou et al.: multi-depth harmonic convolution for solos and stems across instruments. Architecture, mechanism and evidence are covered in the Harmonica chapter.'))}${card('TUTTI · 2026',t('从音频到乐谱结构','From audio to notation'),t('研究合成预训练与真实微调的audio-to-score；目标包含记谱结构，和音符事件任务有区别。','Studies synthetic pretraining and real-data adaptation for audio-to-score; notation structure differs from timed-note events.'))}</div>`+takeaway(t('比较“当前方法”之前，先对齐它们到底在解决什么任务。','Before comparing current methods, align the tasks they actually solve.')),
    note:t("这些文献构成截至2026-10-13的选择性研究概览，而非穷尽式综述。预训练表征、不区分乐器的高效转录和直接记谱具有不同目标与评测协议，不应合并成单一排行榜。","These papers form a selective research snapshot as of 2026-10-13, rather than an exhaustive survey. Pretrained representations, efficient instrument-agnostic transcription and direct notation have different objectives and evaluation protocols and should not be merged into a single ranking."),sources:src('challenge','harmonica','tutti')},
  {id:'discussion',chapter:'discussion',kicker:'OPEN RESEARCH QUESTIONS',
    title:t("开放研究问题","Open research questions"),
    lead:t('多乐器转录的核心，是让音高、时间与乐器身份同时可信。MuScriptor展示了数据与后训练的力量，也让评测和表示边界更值得讨论。','Multi-instrument transcription must get pitch, time and instrument identity right together. MuScriptor highlights the power of data and post-training—and the importance of evaluation and representation.'),
    html:`<div class="qa-list"><div><span class="q-number">01</span><section><h3>${t('接下来最缺什么：架构、数据，还是标注？','What is missing most: architecture, data or labels?')}</h3><p>${t('如果只能投入一次标注预算，会优先提高覆盖、对齐，还是完整性？','With one annotation budget, would you prioritize coverage, alignment or completeness?')}</p></section></div><div><span class="q-number">02</span><section><h3>${t('我们应该奖励“分数”，还是奖励“可编辑性”？','Should we optimize scores or editability?')}</h3><p>${t('乐器身份、音符边界与乐谱结构，哪个最影响下游使用？','Which matters most downstream: instrument identity, note boundaries or score structure?')}</p></section></div><div><span class="q-number">03</span><section><h3>${t('同类乐器的多个声部，要不要单独表示？','Should multiple players of one instrument be represented separately?')}</h3><p>${t('当两个小提琴声部同音高重叠，当前事件表示够用吗？','When two violin parts overlap at one pitch, is the current event representation enough?')}</p></section></div></div>${link('#library',t('文献库与延伸阅读','Paper library & further reading'))}`,
    note:t("后续研究需要同时关注数据覆盖与标注质量、面向下游使用的评测，以及同类乐器多声部的表示。对 MuScriptor 的进一步分析可以围绕等量高质量数据的监督微调对照、无参考乐器条件评测和冲突音符保留设定展开。","Further research must consider data coverage and label quality, evaluation for downstream use, and representations for multiple parts of the same instrument. Further analysis of MuScriptor could examine supervised fine-tuning with the same checked data, evaluation without reference instrument conditions, and protocols retaining conflicting notes."),sources:[]}
  ];
  const chapters = [
    {id:'start',label:t('任务定义','Task definition'),first:'intro'},
    {id:'problem',label:t('挑战与方法','Challenges & methods'),first:'ambiguity'},
    {id:'literature',label:t('代表性文献','Representative literature'),first:'landmarks'},
    {id:'evidence',label:t('评测与数据','Evaluation & data'),first:'metrics'},
    {id:'harmonica',label:t('Harmonica · 谐波建模','Harmonica · harmonic modeling'),first:'harmonica'},
    {id:'muscriptor',label:t('MuScriptor','MuScriptor'),first:'muscriptor'},
    {id:'discussion',label:t('研究方向与问题','Directions & open questions'),first:'frontiers'}
  ];
  const papers = [
    {id:'nmf',year:2003,title:'Non-negative Matrix Factorization for Polyphonic Music Transcription',authors:'Paris Smaragdis · Judith C. Brown',venue:'WASPAA 2003',kind:'foundation',url:P.nmf,summary:t('把频谱分解成模板与激活，建立可解释的复音转录思路。','Decomposes spectrograms into templates and activations for interpretable polyphonic transcription.'),insight:t('X ≈ WH 提供简洁的建模语言；后来许多工作仍在处理模板、音高和时间结构的关系。','X ≈ WH supplies a compact modeling language that makes spectral, pitch and temporal structure explicit.'),limit:t('不是通用多乐器系统；稳定谐波与音色模板的假设限制真实复杂混音。','Not a general multi-instrument system; stable harmonic templates limit realism in complex mixtures.')},
    {id:'onsets',year:2018,title:'Onsets and Frames: Dual-Objective Piano Transcription',authors:'Curtis Hawthorne et al.',venue:'ISMIR 2018 · preprint 2017',kind:'foundation',url:P.onsets,demo:'https://magenta.tensorflow.org/onsets-frames',summary:t('钢琴转录里程碑：把起音与持续状态分开预测，再结合解码。','A piano milestone: jointly model note onsets and sustained frame activity.'),insight:t('起音预测帮助帧网络，并约束新音符的生成，改善重复音与边界处理。','Onset predictions inform the frame network and gate new notes during decoding.'),limit:t('钢琴专用，不解决乐器归属；列入这里是为了说明关键建模思想。','Piano-only; does not solve instrument attribution. Included as a conceptual bridge.')},
    {id:'slakh',year:2019,title:'Cutting Music Source Separation Some Slakh: A Dataset to Study the Impact of Training Data Quality and Quantity',authors:'Ethan Manilow · Gordon Wichern · Prem Seetharaman · Jonathan Le Roux',venue:'WASPAA 2019',kind:'data',url:P.slakh,demo:'http://www.slakh.com/',summary:t('MIDI渲染得到混音、分轨与符号监督；Slakh2100首版含2100首、约145小时混音。','MIDI rendering produces mixtures, stems and symbolic labels. The first Slakh2100 release has 2,100 tracks and about 145 hours of mixtures.'),insight:t('让多乐器配对数据可扩展，是后续方法的重要数据基础。','Makes paired multi-instrument supervision scalable for later methods.'),limit:t('原论文关注数据和分离；它不是新转录模型，合成表现也不等于真实迁移。','The original contribution concerns data and separation, not a new transcription model; synthetic performance does not establish real transfer.')},
    {id:'maestro',year:2019,title:'Enabling Factorized Piano Music Modeling and Generation with the MAESTRO Dataset',authors:'Curtis Hawthorne et al.',venue:'ICLR 2019',kind:'data',url:'https://arxiv.org/abs/1810.12247',demo:'https://magenta.tensorflow.org/datasets/maestro',summary:t('高质量对齐的真实钢琴音频与MIDI；作为“精确配对数据”的参考例子。','Precisely aligned real piano audio and MIDI: an example of high-quality paired data.'),insight:t('可靠时间对齐有助于研究起音、结束与演奏细节。','Reliable alignment supports modeling of note boundaries and performance detail.'),limit:t('钢琴数据集，不应被当作多乐器真实混音评测。','A piano dataset, not an evaluation of real multi-instrument mixtures.')},
    {id:'mt3',year:2022,title:'MT3: Multi-Task Multitrack Music Transcription',authors:'Josh Gardner · Ian Simon · Ethan Manilow · Curtis Hawthorne · Jesse Engel',venue:'ICLR 2022 · preprint 2021',kind:'method',url:P.mt3,code:'https://github.com/magenta/mt3',demo:'https://storage.googleapis.com/mt3/index.html',summary:t('用共享词表与Transformer，把多种数据集的音频统一解码为多轨事件。','Uses a shared vocabulary and Transformer to decode audio from multiple datasets into multitrack events.'),insight:t('2.048秒片段，10ms绝对时间位置，tie衔接活动音符；任务统一不必依赖单独的乐器网络。','2.048-second segments, 10 ms absolute time positions and ties for active notes enable a unified event model.'),limit:t('跨段一致性、乐器归属与密集复音仍有挑战；原始多乐器模型不预测细粒度力度。','Cross-chunk consistency, instrument attribution and dense polyphony remain difficult; no graded velocity prediction in the original multi-instrument model.')},
    {id:'jointist',year:2023,title:'Jointist: Simultaneous Improvement of Multi-instrument Transcription and Music Source Separation via Joint Training',authors:'Kin Wai Cheuk et al.',venue:'arXiv 2023',kind:'method',url:P.jointist,code:'https://github.com/KinWaiCheuk/Jointist',demo:'https://jointist.github.io/Demo/',summary:t('把乐器识别、条件转录和分离连接起来，让相关任务共享监督。','Connects instrument recognition, conditioned transcription and source separation through joint training.'),insight:t('预测的piano roll引导分离；用户可指定乐器。它不是简单先分离再逐轨转录。','Predicted piano rolls guide separation and users can supply instruments; not simply a separation-first pipeline.'),limit:t('识别错误可能传播；模块与指标不同，不能以一项听评优势概括所有任务。','Recognition errors can propagate; listening-test gains do not imply dominance across every objective metric.')},
    {id:'perceiver',year:2023,title:'Multitrack Music Transcription with a Time-Frequency Perceiver',authors:'Wei-Tsung Lu · Ju-Chiang Wang · Yun-Ning Hung',venue:'ICASSP 2023',kind:'method',url:P.perceiver,summary:t('用潜变量查询时频特征，建模多轨piano roll；连接到YourMT3+的编码器设计。','Uses latent queries over time-frequency features for multitrack piano rolls; a foundation for the YourMT3+ encoder.'),insight:t('论文覆盖12个乐器类别及人声，显示对时频输入结构的建模价值。','Models 12 instrument classes plus vocals, highlighting the value of structured time-frequency processing.'),limit:t('输出表示与事件解码系统不同，不能忽略任务和类别粒度直接排序。','Output representation and class granularity differ from event-decoding systems.')},
    {id:'yourmt3',year:2024,title:'YourMT3+: Multi-instrument Music Transcription with Enhanced Transformer Architectures and Cross-dataset Stem Augmentation',authors:'Sungkyun Chang · Emmanouil Benetos · Holger Kirchhoff · Simon Dixon',venue:'IEEE MLSP 2024 · arXiv v3',kind:'method',url:P.yourmt3,code:'https://github.com/mimbres/YourMT3',summary:t('PerceiverTF、MoE、多通道解码和跨数据集分轨增强，共同提升转录与标签利用。','Combines PerceiverTF, MoE, multi-channel decoding and cross-dataset stem augmentation.'),insight:t('多通道允许对未标注乐器屏蔽损失；“缺失标签”不能直接被理解为“乐器不存在”。','Multiple channels enable masking losses for unannotated instruments: missing labels do not imply absent instruments.'),limit:t('真实流行音乐依然困难；不能把整个增益只归因于MoE。','Real pop remains challenging; gains cannot be attributed solely to MoE.')},
    {id:'mu',year:2026,title:'MuScriptor: An Open Model for Multi-Instrument Music Transcription',authors:'Simon Rouard · Michael Krause · Axel Roebel · Carl-Johann Simon-Gabriel · Alexandre Défossez',venue:'ISMIR 2026 · arXiv v2 (2026-08-03)',kind:'focus',url:'https://arxiv.org/abs/2607.08168v2',code:'https://github.com/muscriptor/muscriptor',demo:'https://muscriptor.kyutai.org/',summary:t('仅解码器模型，用合成预训练、真实微调和强化学习后训练改善真实混音转录。','Decoder-only transcription with synthetic pretraining, real-audio fine-tuning and reinforcement post-training.'),insight:t('主表Multi F1：15.2→41.7→48.2（CFG=1）。内部372首、1.3B、参考乐器条件、重叠参考音符过滤。公开集表2的YourMT3+→MuScriptor Multi F1：Bach10 26.4→34.7；ChoirSet 2.6→11.5；PHENICX 12.2→25.7；RWC-P 19.1→25.6；RWC-C 40.5→36.0；RWC-G 17.2→23.7；RWC-J 26.4→31.8；RWC-R 23.1→20.3。均为作者报告。','Main Multi F1: 15.2→41.7→48.2 (CFG=1): internal 372-track test, 1.3B, reference instrument conditions, overlapping reference notes filtered. Table 2 public-set YourMT3+→MuScriptor Multi F1: Bach10 26.4→34.7; ChoirSet 2.6→11.5; PHENICX 12.2→25.7; RWC-P 19.1→25.6; RWC-C 40.5→36.0; RWC-G 17.2→23.7; RWC-J 26.4→31.8; RWC-R 23.1→20.3. All author-reported.'),limit:t('保留冲突音符时Multi降为42.0；内部真实语料限制训练复现；默认真实乐器条件并非完全盲转录。代码MIT，权重CC BY-NC 4.0，论文CC BY 4.0。当前仓库small/medium/large分别103M/307M/1.4B，与论文尺寸命名分开。','Multi falls to 42.0 with conflicting notes retained. Internal real data limits training reproduction; reference instrument conditions are not blind transcription. Code: MIT; weights: CC BY-NC 4.0; paper: CC BY 4.0. Current released sizes are 103M/307M/1.4B, distinct from the paper’s size labels.')},
    {id:'challenge',year:2026,title:'Advancing Multi-Instrument Music Transcription: Results from the 2025 AMT Challenge',authors:'Ojas Chaturvedi et al.',venue:'arXiv 2026 · reports the 2025 challenge',kind:'recent',url:P.challenge,summary:t('统一挑战赛报告：8支有效提交队伍，2支超过MT3基线；MIROS使用MusicFM与条件多解码器。','Shared challenge report: eight valid teams, two above the MT3 baseline; MIROS uses MusicFM and conditioned decoders.'),insight:t('预训练音乐表征提供另一条路线，统一评测仍暴露复音与音色变化难点。','Pretrained representations offer another route, while shared evaluation exposes polyphony and timbre challenges.'),limit:t('76段合成短曲，至多3种乐器；不能据此宣称密集商业混音全面领先。','Only 76 synthesized short pieces, with at most three instruments; not evidence of universal performance on dense commercial recordings.')},
    {id:'harmonica',year:2026,title:'Harmonica: Accurate and Lightweight Instrument-Agnostic Music Transcription',authors:'Longshen Ou · Héctor Martel · Joe Hennessy-Priest · Taemin Cho',venue:'arXiv v1 · 2026-09-04 · submitted to ICASSP 2027',kind:'recent',url:P.harmonica,demo:'https://www.oulongshen.xyz/amt',summary:t('跨乐器的单乐器/分轨转录：CQT输入、多深度谐波卷积与逐帧预测，强调准确率和计算效率。','Transcribes solos/stems across instruments using CQT, multi-depth harmonic convolution and frame-level prediction, emphasizing accuracy and efficiency.'),insight:t('Offset头只作辅助监督；多层谐波聚合优于单层，shift-and-aggregate减少重复参数。提供nano至x-large模型及8个测试集的系统评测，方法与原图见Harmonica专章。','Offsets provide auxiliary supervision only. Multi-depth aggregation improves on single-depth; shift-and-aggregate removes redundant parameters. Models span nano to x-large, with eight test sets; see the Harmonica chapter for the method and original figures.'),limit:t('输入为独奏/独立分轨，无乐器归属目标；不是多乐器混音基准。速度依硬件与实现而变；MuScriptor对照为medium已发布权重，并非其论文1.3B设置。','Inputs are solos/isolated stems, without an attribution target; this is not a mixture benchmark. Speed depends on hardware and implementation. The MuScriptor baseline uses released medium weights rather than the paper’s 1.3B setting.')},
    {id:'tutti',year:2026,title:'TUTTI: Toward generalizable audio-to-score transcription via fully synthesized data',authors:'Jianhuai Hu et al.',venue:'arXiv 2026-09',kind:'recent',url:P.tutti,summary:t('相邻方向：面向乐谱结构的音频转录，研究全合成数据预训练和真实数据微调。','Adjacent task: notation-level audio-to-score, with synthetic pretraining and real-data fine-tuning.'),insight:t('从“音符事件正确”继续走向“可读谱面结构正确”。','Extends the question from correct note events to correct notation structure.'),limit:t('目标与评测不同，不组成直接排行榜；论文的计划发布不等于资源已全部公开。','Targets and metrics differ, so this is not a direct leaderboard entry; planned release is not evidence that all resources are already public.')}
  ];
  return {slides,chapters,papers};
};
